string host = Tama.Args.Get(args, "hostTitle", "");
Document d = null;
foreach (Document x in app.Documents) if (x.Title == host) d = x;
if (d == null) return "host not open";
return new FilteredElementCollector(d).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>()
  .Select(li => { var t = li.GetTransform(); return new {
     id = li.Id.IntegerValue, name = li.Name,
     mirrored = t.BasisX.CrossProduct(t.BasisY).Z < 0,
     rot_deg = Math.Round(Math.Atan2(t.BasisX.Y,t.BasisX.X)*180/Math.PI,4),
     workset = d.GetWorksetTable().GetWorkset(li.WorksetId).Name
  };}).ToList();
